fn total(angka: &Vec<i32>) -> i32 {
    let mut t = 0;
    for n in angka {
        t += n;
    }
    t
}

fn tambah_satu(angka: &mut Vec<i32>) {
    for n in angka.iter_mut() {
        *n += 1;              // * untuk menyentuh nilai di balik referensi
    }
}

