// Display: bagaimana manusia membacanya
impl fmt::Display for Versi {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "v{}.{}.{}", self.mayor, self.minor, self.tambal)
    }
